package servicio;
import config.ConfiguracionMercadoPago;import dao.*;import java.math.*;import java.time.*;import negocio.*;import pagos.*;
public class CreacionOrdenPagoClienteService {
 private final OrdenPagoDAO dao;private final PagoService pagos;private final OrdenPagoService dominio;private final Clock clock;private final PasarelaPagoOnline pasarela;private final IntentoPagoService intentos;private final ConfiguracionMercadoPago config;private final ConsultaOrdenPagoClienteService conciliacion;
 public CreacionOrdenPagoClienteService(){this(new OrdenPagoDAOMySQL(),new PagoService(),new OrdenPagoService(),Clock.systemDefaultZone(),PasarelaPagoFactory.crear(ConfiguracionMercadoPago.cargar()),new IntentoPagoService(),ConfiguracionMercadoPago.cargar());}
 public CreacionOrdenPagoClienteService(OrdenPagoDAO d,PagoService p,OrdenPagoService s,Clock c){this(d,p,s,c,new PasarelaPagoNoDisponible("Pago online no configurado."),null,null);}
 public CreacionOrdenPagoClienteService(OrdenPagoDAO d,PagoService p,OrdenPagoService s,Clock c,PasarelaPagoOnline pa,IntentoPagoService i,ConfiguracionMercadoPago cfg){if(d==null||p==null||s==null||c==null||pa==null)throw new IllegalArgumentException("Las dependencias son obligatorias.");dao=d;pagos=p;dominio=s;clock=c;pasarela=pa;intentos=i;config=cfg;conciliacion=new ConsultaOrdenPagoClienteService(d,c,pa,new AcreditacionOrdenPagoTransaccionalService());}
 public OrdenPago crearManual(long reservaId,BigDecimal senia,LocalDateTime vence){BigDecimal faltante=faltante(reservaId,senia);String clave="reserva:"+reservaId+":senia:"+faltante.toPlainString()+":manual";OrdenPago previa=dao.buscarPorIdempotencia(clave);if(previa!=null)return previa;OrdenPago o=base(reservaId,faltante,vence,clave);o.setProveedor(ProveedorPago.MANUAL);o.setMetodo(MetodoOrdenPago.TRANSFERENCIA_MANUAL);o.setEstado(EstadoOrdenPago.ESPERANDO_VERIFICACION);return dao.guardar(dominio.preparar(o));}
 public OrdenPago crearOnline(long reservaId,BigDecimal senia,LocalDateTime vence,String descripcion){if(!pasarela.disponible()||config==null||!config.disponible())throw new IllegalStateException("El pago online no está disponible.");BigDecimal faltante=faltante(reservaId,senia);String clave="reserva:"+reservaId+":senia:"+faltante.toPlainString()+":mercado-pago";OrdenPago previa=dao.buscarPorIdempotencia(clave);if(previa!=null)previa=conciliacion.conciliar(previa);if(previa!=null&&previa.getEstado()==EstadoOrdenPago.APROBADA)return previa;if(previa!=null&&previa.getEstado()==EstadoOrdenPago.ESPERANDO_PAGO&&previa.getUrlPago()!=null)return previa;OrdenPago o=previa;if(o==null){o=base(reservaId,faltante,vence,clave);o.setProveedor(ProveedorPago.MERCADO_PAGO);o.setMetodo(MetodoOrdenPago.PAGO_ONLINE);o.setEstado(EstadoOrdenPago.CREADA);o.setReferenciaExterna("orden:"+reservaId+":"+clave.hashCode());o=dao.guardar(dominio.preparar(o));}IntentoPago intento=intentos.iniciar(o.getId());try{SolicitudCheckout solicitud=new SolicitudCheckout(o.getId(),reservaId,o.getImporte(),o.getMoneda(),descripcion,o.getReferenciaExterna(),vence,config.retornoExitoso(),config.retornoPendiente(),config.retornoFallido(),config.webhookUrl(),clave+":intento:"+intento.getNumeroIntento());CheckoutCreado checkout=pasarela.crearCheckout(solicitud);if(!dao.completarCheckout(o.getId(),o.getVersion(),checkout.preferenciaId(),checkout.checkoutUrl().toString())){OrdenPago actual=dao.buscar(o.getId());if(actual==null||actual.getUrlPago()==null)throw new IllegalStateException("La orden cambió antes de guardar el checkout.");o=actual;}else{o.setPreferenciaExternaId(checkout.preferenciaId());o.setUrlPago(checkout.checkoutUrl().toString());o.setEstado(EstadoOrdenPago.ESPERANDO_PAGO);o.setVersion(o.getVersion()+1);}intentos.exitoso(intento.getId(),checkout.preferenciaId());return o;}catch(RuntimeException e){intentos.error(intento.getId(),e.getMessage());throw e;}}
 private BigDecimal faltante(long reservaId,BigDecimal senia){if(reservaId<=0)throw new IllegalArgumentException("La reserva es obligatoria.");BigDecimal x=(senia==null?BigDecimal.ZERO:senia).subtract(pagos.totalAcreditado(reservaId)).max(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP);if(x.signum()<=0)throw new IllegalStateException("La seña ya está cubierta.");return x;}
 private OrdenPago base(long reservaId,BigDecimal importe,LocalDateTime vence,String clave){OrdenPago o=new OrdenPago();o.setReservaId(reservaId);o.setImporte(importe);o.setClaveIdempotencia(clave);o.setFechaExpiracion(vence);o.setFechaCreacion(LocalDateTime.now(clock));return o;}
}
